-- Segunda corrección del avatar de El Chanty (oct/2026): el recorte
-- anterior (migración 0011) incluía margen blanco alrededor de la
-- cara, no justo el círculo visible en X. Como la tarjeta estira esa
-- imagen cuadrada para llenar el círculo del avatar, ese margen
-- blanco se colaba adentro y encogía la cara. Este recorte es exacto
-- al borde del círculo real (medido en píxeles sobre el pantallazo
-- de X de El Chanty), así que ahora sí llena el círculo de punta a
-- punta, igual que El Traveler.
update paginas set
  avatar_url = 'data:image/jpeg;base64,'
where nombre = 'El Chanty';
